import fs from "fs";
import path from "path";
import type { TrapBundle } from "@/types/traps";

/**
 * Interview-trap replays. Each file in content/traps/ is a trace.json
 * generated by github.com/somnathraz/interview-traps (`npm run trace`),
 * copied here by `npm run traps:sync`.
 */
const trapsDirectory = path.join(process.cwd(), "content/traps");

export const TRAPS_REPO_URL = "https://github.com/somnathraz/interview-traps";

export function getAllTraps(): TrapBundle[] {
    if (!fs.existsSync(trapsDirectory)) return [];
    return fs
        .readdirSync(trapsDirectory)
        .filter((name) => name.endsWith(".json"))
        .map((name) => JSON.parse(fs.readFileSync(path.join(trapsDirectory, name), "utf8")) as TrapBundle)
        .filter((trap) => trap.schemaVersion === 1)
        .sort((a, b) => a.number - b.number);
}

export function getTrapBySlug(slug: string): TrapBundle | undefined {
    return getAllTraps().find((trap) => trap.slug === slug);
}
